import{_ as r,c as e,d as l,Z as t}from"./chunks/framework.B0uuYL3Y.js";const p=JSON.parse('{"title":"微架构安全入门","description":"从缓存、取指和执行学起，再沿共享资源与瞬态执行等路线分析微架构安全问题。","frontmatter":{"title":"微架构安全入门","description":"从缓存、取指和执行学起，再沿共享资源与瞬态执行等路线分析微架构安全问题。","date":"2026-11-25","tags":["微架构安全","导论","Spectre","Meltdown"],"bookTitle":"微架构安全"},"headers":[],"relativePath":"posts/microarch-00-intro.md","filePath":"posts/microarch-00-intro.md"}'),o={name:"posts/microarch-00-intro.md"};function i(h,a,c,n,s,m){return e(),l("div",null,a[0]||(a[0]=[t('<p>两个线程各自修改不同的计数器，为什么还会等待对方？一条指令最终没有提交，为什么它先前发出的请求仍可能改变缓存？这两个问题都要追踪程序结果之外的硬件状态。前者可以从缓存行和写权限讲起，后者需要理解预测、异常和指令退休。</p><p>微架构是指实现指令集的软件可见规则所用的硬件组织。处理器可以保存数据副本、预测后续访存和下一条指令的地址，也可以先执行暂时不必交付结果的操作。这些行为平时用于提高速度。某些内部状态会影响之后的访问时间。当受保护的信息能够改变这些状态时，时间就可能成为分析安全边界的一部分。</p><h2 id="本书怎样展开" tabindex="-1">本书怎样展开 <a class="header-anchor" href="#本书怎样展开" aria-label="Permalink to &quot;本书怎样展开&quot;">​</a></h2><p><strong>Spectre</strong> 原始研究的一条路径从错误的控制流预测出发。处理器沿着预测路径执行了一段操作，发现方向不对后丢弃结果。<strong>Meltdown</strong> 原始研究则表明，在论文讨论的受影响处理器上，一次在架构上会被权限拒绝的加载，可能在报告异常前影响后续的内部操作。这两个例子共同引出一个问题：如果相关指令的结果没有正式生效，哪些内部状态还可能使它的影响留到后来？</p><p>读者应会基本的十六进制运算，知道寄存器、地址和数组的含义。要理解共享资源，先读「访存局部性与高速缓存」，从本地命中跟到多核写权限，再用第五、六章分析不同的时间差。要理解瞬态执行，可以先读地址翻译、指令执行和分支预测，再分别读两种漏洞机制。带着具体问题来查阅时，可以直接进入相应文章，按正文线索补足先修知识。</p><h2 id="book-contents" tabindex="-1">目录 <a class="header-anchor" href="#book-contents" aria-label="Permalink to &quot;目录 {#book-contents}&quot;">​</a></h2><h3 id="第一章-访存局部性与高速缓存" tabindex="-1">第一章　访存局部性与高速缓存 <a class="header-anchor" href="#第一章-访存局部性与高速缓存" aria-label="Permalink to &quot;第一章　访存局部性与高速缓存&quot;">​</a></h3><p>先从地址算出数据所在的缓存行，再用组相联模型逐次判断命中。等到能推算一串访问的代价，就可以分析同一时刻仍在等待的多条请求。</p><ol><li><a href="./microarch-01-cache.html">缓存行与局部性</a></li><li><a href="./microarch-01b-cache-mapping.html">缓存怎样查找和替换一行</a></li><li><a href="./microarch-01d-cache-traversal.html">矩阵按行读和按列读的缓存开销</a></li><li><a href="./microarch-01a-mshr.html">缓存未命中后如何合并请求</a></li><li><a href="./microarch-01e-cache-stores.html">写入缓存后，数据什么时候送到下一级</a></li><li><a href="./microarch-01f-coherence.html">两个核心怎样读到同一份新数据</a></li><li><a href="./microarch-01g-false-sharing.html">两个线程改不同字段，为什么缓存行还会来回传</a></li></ol><h3 id="第二章-硬件预取器" tabindex="-1">第二章　硬件预取器 <a class="header-anchor" href="#第二章-硬件预取器" aria-label="Permalink to &quot;第二章　硬件预取器&quot;">​</a></h3><p>步长预测器从已经出现的访问推算后续地址。追踪候选地址时，会遇到两个独立的问题：资源能否容纳这次请求，以及跨页地址能否正确翻译。</p><ol><li><a href="./microarch-02-prefetch.html">硬件预取器怎样工作</a></li><li><a href="./microarch-02d-prefetch-rtl.html">预取器和数据缓存怎样握手</a></li></ol><h3 id="第三章-地址翻译" tabindex="-1">第三章　地址翻译 <a class="header-anchor" href="#第三章-地址翻译" aria-label="Permalink to &quot;第三章　地址翻译&quot;">​</a></h3><p>先用一个地址走完三级页表，再看 TLB 缓存哪些翻译结果，以及如何让旧映射失效。</p><ol><li><a href="./microarch-02a-translation.html">处理器怎样用页表和 TLB 翻译地址</a></li></ol><h3 id="第四章-指令执行与分支预测" tabindex="-1">第四章　指令执行与分支预测 <a class="header-anchor" href="#第四章-指令执行与分支预测" aria-label="Permalink to &quot;第四章　指令执行与分支预测&quot;">​</a></h3><p>先跟踪一条指令从执行到退休，再用一段代码分辨寄存器依赖和内存依赖。把视线移到前端后，沿同一次取指学习目标、方向和历史各自怎样参与预测，再推演猜错以后的恢复。</p><ol><li><a href="./microarch-03-execution.html">乱序执行怎样按程序顺序退休</a></li><li><a href="./microarch-03d-load-store.html">加载怎样从存储队列拿到数据</a></li><li><a href="./microarch-03a-fetch-prediction.html">分支预测器怎样决定下一次取指</a></li></ol><h3 id="第五章-计时与证据" tabindex="-1">第五章　计时与证据 <a class="header-anchor" href="#第五章-计时与证据" aria-label="Permalink to &quot;第五章　计时与证据&quot;">​</a></h3><p>用对照条件判断时间差来自哪一段过程，再检查给定的观察者究竟能从差异中推断什么。</p><ol><li><a href="./microarch-04a-measurement.html">用计时和计数器分析访存</a></li><li><a href="./microarch-04b-observation.html">时间差何时算作侧信道证据</a></li></ol><h3 id="第六章-共享资源与隔离" tabindex="-1">第六章　共享资源与隔离 <a class="header-anchor" href="#第六章-共享资源与隔离" aria-label="Permalink to &quot;第六章　共享资源与隔离&quot;">​</a></h3><p>把两个工作负载放在一起，先算末级缓存的组内替换，再沿内存控制器的读队列追到 DRAM 行缓冲。最后回到同一个缓存组，推算分配掩码改变了哪些替换，再看任务迁移后会用哪份掩码。</p><ol><li><a href="./microarch-06a-shared-cache.html">不同的数据为什么会在末级缓存里互相挤掉</a></li><li><a href="./microarch-06b-memory-queue.html">未命中次数相同，为什么内存等待更长</a></li><li><a href="./microarch-06c-cat.html">划分末级缓存的路能隔离什么</a></li></ol><h3 id="第七章-瞬态执行" tabindex="-1">第七章　瞬态执行 <a class="header-anchor" href="#第七章-瞬态执行" aria-label="Permalink to &quot;第七章　瞬态执行&quot;">​</a></h3><p>沿指令读两种漏洞的执行过程。先看条件分支误预测与权限异常各自怎样产生瞬态活动，再把分析扩展到间接目标与访存顺序。</p><ol><li><a href="./microarch-04d-spectre-v1.html">Spectre v1 中的边界检查为何会被越过</a></li><li><a href="./microarch-04e-meltdown.html">Meltdown 中的越权加载如何影响后续指令</a></li><li><a href="./microarch-04c-variants.html">Spectre 变体中的分支与访存推测</a></li></ol><p>读到例题时，先按题设复算一次，再对照手册确认哪些条件可以用于具体处理器。更换行长、替换策略或观察条件时，可以用原来的推理方法重新计算。 <a href="./microarch-05-sources.html">微架构安全学习资料</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://spectreattack.com/spectre.pdf" target="_blank" rel="noreferrer">Spectre 原论文</a></li><li><a href="https://meltdownattack.com/meltdown.pdf" target="_blank" rel="noreferrer">Meltdown 原论文</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-01-cache.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>缓存行与局部性</strong></span></a></p></nav>',31)]))}const f=r(o,[["render",i]]);export{p as __pageData,f as default};
